package __PACKAGE__;

import com.mojang.brigadier.StringReader;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import java.util.ArrayList;
import java.util.List;
import net.minecraft.core.particles.ParticleOptions;
import net.minecraft.core.particles.ParticleType;
import net.minecraft.network.FriendlyByteBuf;

/**
 * What the server sends to play or stop a Sparkle system (Minecraft 1.20 to 1.20.4): the system, the entity it
 * follows (-1: none), the action and the values of its user parameters.
 * Generated by the Sparkle plugin: do not edit, it is written again when the runtime is updated.
 */
public record SparkleOptions(String system, int entity, int action, List<Parameter> parameters) implements ParticleOptions {
    public static final int PLAY = 0;
    public static final int STOP = 1;

    /** The value of a user parameter: x for a number, x y z for a vector or a color. */
    public record Parameter(String name, double x, double y, double z) {
        public static final Codec<Parameter> CODEC = RecordCodecBuilder.create(instance -> instance.group(
                Codec.STRING.fieldOf("name").forGetter(Parameter::name),
                Codec.DOUBLE.fieldOf("x").forGetter(Parameter::x),
                Codec.DOUBLE.fieldOf("y").forGetter(Parameter::y),
                Codec.DOUBLE.fieldOf("z").forGetter(Parameter::z)).apply(instance, Parameter::new));
    }

    public static final Codec<SparkleOptions> CODEC = RecordCodecBuilder.create(instance -> instance.group(
            Codec.STRING.fieldOf("system").forGetter(SparkleOptions::system),
            Codec.INT.optionalFieldOf("entity", -1).forGetter(SparkleOptions::entity),
            Codec.INT.optionalFieldOf("action", PLAY).forGetter(SparkleOptions::action),
            Parameter.CODEC.listOf().optionalFieldOf("parameters", List.of()).forGetter(SparkleOptions::parameters)).apply(instance, SparkleOptions::new));

    @SuppressWarnings("deprecation")
    public static final ParticleOptions.Deserializer<SparkleOptions> DESERIALIZER = new ParticleOptions.Deserializer<>() {
        @Override
        public SparkleOptions fromCommand(ParticleType<SparkleOptions> type, StringReader reader) {
            // "/particle mymod:sparkle mymod:fire": plays the system named after the type.
            String system = reader.canRead() ? reader.getRemaining().trim() : "";
            reader.setCursor(reader.getTotalLength());
            return new SparkleOptions(Sparkle.key(system), -1, PLAY, List.of());
        }

        @Override
        public SparkleOptions fromNetwork(ParticleType<SparkleOptions> type, FriendlyByteBuf buffer) {
            String system = buffer.readUtf();
            int entity = buffer.readVarInt();
            int action = buffer.readVarInt();
            int count = buffer.readVarInt();
            List<Parameter> parameters = new ArrayList<>(count);
            for (int i = 0; i < count; i++) {
                parameters.add(new Parameter(buffer.readUtf(), buffer.readDouble(), buffer.readDouble(), buffer.readDouble()));
            }

            return new SparkleOptions(system, entity, action, parameters);
        }
    };

    @Override
    public ParticleType<?> getType() {
        return Sparkle.TYPE;
    }

    @Override
    public void writeToNetwork(FriendlyByteBuf buffer) {
        buffer.writeUtf(system);
        buffer.writeVarInt(entity);
        buffer.writeVarInt(action);
        buffer.writeVarInt(parameters.size());
        for (Parameter parameter : parameters) {
            buffer.writeUtf(parameter.name());
            buffer.writeDouble(parameter.x());
            buffer.writeDouble(parameter.y());
            buffer.writeDouble(parameter.z());
        }
    }

    @Override
    public String writeToString() {
        return Sparkle.TYPE_NAME + " " + system;
    }
}
